mapper.select:
SELECT need.id, need.need_quantity-need.scheduling_quantity quantity, need.product_id, task.ask_complete_time, artifact.serial_number, project.id 'project.id', project.`name` 'project.`name`', project.short_name 'project.short_name', project.serial_number 'project.serial_number', monomer.id 'monomer.id', monomer.`name` 'monomer.`name`', area.id 'area.id', area.`name` 'area.name', workshop.id 'workshop.id', workshop.`name` 'workshop.name', production_line.id 'production_line.id', production_line.`name` 'production_line.name', gro.id 'groups.id', gro.`name` 'groups.name' FROM mes_building_task_need_machine_part_scheduling need LEFT JOIN mes_building_task task ON need.task_id = task.id LEFT JOIN tech_artifact artifact ON artifact.id=task.product_id LEFT JOIN contract_project project ON need.id = project.id LEFT JOIN plan_monomer monomer ON need.monomer_id = monomer.id LEFT JOIN plan_area area ON need.area_id = area.id LEFT JOIN mes_building_workshop workshop ON need.workshop_id = workshop.id LEFT JOIN mes_building_production_line production_line ON need.production_line_id = production_line.id LEFT JOIN mes_building_groups gro ON need.groups_id = gro.id
need.bool_delete_enum=0 and need.id in
#{id}

SELECT workshop.id id, workshop.`name` name FROM mes_building_task_need_machine_part_scheduling need LEFT JOIN mes_building_workshop workshop ON workshop.id = need.workshop_id and workshop.bool_delete_enum = 0 LEFT JOIN tech_machine_part machine_part ON machine_part.id = need.product_id and machine_part.bool_delete_enum = 0 WHERE need.bool_delete_enum = 0
AND DATE_FORMAT( need.ask_complete_time, '%Y-%m' ) IN (#{param.yearMonth})
AND need.send_nesting_status = #{param.sendNestingStatus}
AND machine_part.steel_plate_type_enum in
#{steelPlateTypeEnum}
AND need.project_id IN
#{projectId}
GROUP BY workshop.id

SELECT count(DISTINCT project.id) projectCount, project.id 'project.id', project.name 'project.name', project.serial_number 'project.serial_number', project.short_name 'project.short_name', ANY_VALUE(DATE_FORMAT(need.ask_complete_time, '%Y-%m')) AS 'yearMonthDTO.yearMonth', ANY_VALUE(DATE_FORMAT(need.ask_complete_time, '%Y')) AS 'yearMonthDTO.year', ANY_VALUE(DATE_FORMAT(need.ask_complete_time, '%m')) AS 'yearMonthDTO.month', workshop.id 'workshopTeamDTO.workshopId', workshop.`name` 'workshopTeamDTO.workshopName', ANY_VALUE(need.ask_complete_time) 'workshopTeamDTO.askCompleteTime', sum(need.need_quantity - need.scheduling_quantity) 'schedulingQuantity', sum(need.need_quantity * part.net_weight) 'schedulingWeight' FROM mes_building_task_need_machine_part_scheduling need LEFT JOIN contract_project project ON need.project_id = project.id LEFT JOIN mes_building_workshop workshop ON need.workshop_id = workshop.id LEFT JOIN tech_machine_part part ON part.id = need.product_id WHERE need.bool_delete_enum = 0
AND project.id = #{param.projectId}
AND workshop.id = #{param.workshopId}
AND DATE_FORMAT( need.ask_complete_time, '%Y-%m' ) IN
#{yearMonth}
GROUP BY project.id , project.name , project.serial_number , project.short_name , workshop.id, workshop.`name` , DATE_FORMAT(need.ask_complete_time, '%Y-%m')

SELECT count(DISTINCT project.id) projectCount, project.id 'project.id', project.name 'project.name', project.serial_number 'project.serial_number', project.short_name 'project.short_name', ANY_VALUE(DATE_FORMAT(need.ask_complete_time, '%Y-%m')) AS 'yearMonthDTO.yearMonth', ANY_VALUE(DATE_FORMAT(need.ask_complete_time, '%Y')) AS 'yearMonthDTO.year', ANY_VALUE(DATE_FORMAT(need.ask_complete_time, '%m')) AS 'yearMonthDTO.month', workshop.id 'workshopTeamDTO.workshopId', workshop.`name` 'workshopTeamDTO.workshopName', ANY_VALUE(need.ask_complete_time) 'workshopTeamDTO.askCompleteTime', sum(need.need_quantity) 'needSchedulingQuantity', sum(need.need_quantity - need.scheduling_quantity) 'schedulingQuantity', sum((need.need_quantity - need.scheduling_quantity) * part.net_weight) 'schedulingWeight', sum(need.scheduling_quantity) 'scheduledQuantity', sum(need.scheduling_quantity * part.net_weight) 'scheduledWeight', ANY_VALUE(taskOrder.order_number) AS 'taskOrderDTO.orderNumber', need.task_order_id AS 'taskOrderDTO.taskOrderId', group_concat(DISTINCT concat(need.monomer_id, '&', need.area_id)) AS monomerAndAreaIds FROM mes_building_task_need_machine_part_scheduling need LEFT JOIN contract_project project ON need.project_id = project.id LEFT JOIN mes_building_workshop workshop ON need.workshop_id = workshop.id LEFT JOIN mes_building_task_order taskOrder ON need.task_order_id = taskOrder.id LEFT JOIN tech_machine_part part ON part.id = need.product_id WHERE need.bool_delete_enum = 0
AND project.id = #{param.projectId}
AND need.send_nesting_status = #{param.sendNestingStatus}
AND workshop.id IN
#{wid}
AND DATE_FORMAT( need.ask_complete_time, '%Y-%m' ) IN
#{yearMonth}
AND need.steel_plate_type_enum in
#{steelPlateTypeEnum}
AND need.monomer_id = #{param.monomerId}
AND need.area_id = #{param.areaId}
GROUP BY project.id , project.name , project.serial_number , project.short_name , workshop.id, workshop.`name` , DATE_FORMAT(need.ask_complete_time, '%Y-%m'), need.task_order_id
HAVING sum(need.need_quantity - need.scheduling_quantity) > 0

SELECT need.task_order_id 'order_id', group_concat(need.id) AS task_need_machine_part_scheduling_ids, need.issued_to_nesting_software_status, ANY_VALUE(need.ask_complete_time) 'ask_complete_time', ANY_VALUE(need.id) id, ANY_VALUE(part.specification) specification, ANY_VALUE(CONCAT(part.specification, ' * ', part.material)) specificationAndMaterial, ANY_VALUE(project.id) 'project.id', ANY_VALUE(project.short_name) 'project.short_name', ANY_VALUE(project.serial_number) 'project.serial_number', ANY_VALUE(need.team_id) 'team_id', ANY_VALUE(taskorder.order_number) 'order_number', ANY_VALUE(part.id) 'part_id', ANY_VALUE(part.steel_plate_type_enum) 'steel_plate_type_enum', ANY_VALUE(part.bool_process) bool_process, ANY_VALUE(need.monomer_id) 'monomerId', ANY_VALUE(monomer.name) 'monomerName', ANY_VALUE(need.product_id) 'productId', ANY_VALUE(need.workshop_id) 'workshop_id', ANY_VALUE(steel.id) partTypeId, ANY_VALUE(steel.name) AS partType, ANY_VALUE(part.path) 'path', ANY_VALUE(part.serial_number) 'serial_number', ANY_VALUE(part.material) 'material', ANY_VALUE(part.thick) 'thick', ANY_VALUE(part.width) 'width', sum(need.scheduling_quantity) 'scheduling_quantity', sum(need.need_quantity) 'need_quantity', ANY_VALUE(users.name) 'user_name', ANY_VALUE(DATE_FORMAT(need.scheduling_date, '%Y-%m-%d %H:%i:%S')) 'scheduling_date', ANY_VALUE(jobDirectory.job_name) 'job_name', sum(need.need_quantity - need.scheduling_quantity) 'quantity', sum(part.net_weight) 'weight', sum(need.need_quantity * part.net_weight) 'total_weight', ANY_VALUE(part.length) 'length', ROUND(sum(need.need_quantity * part.length)) 'total_length', ROUND(sum(part.surface_area) / 1000000, 8) 'area', ROUND(sum(need.need_quantity * part.surface_area) / 1000000, 8) 'total_area', part.bool_send_directly FROM mes_building_task_need_machine_part_scheduling need LEFT JOIN mes_building_task_order taskorder ON need.task_order_id = taskorder.id LEFT JOIN contract_project project ON need.project_id = project.id LEFT JOIN tech_machine_part part ON part.id = need.product_id LEFT JOIN mes_building_workshop workshop ON need.workshop_id = workshop.id LEFT JOIN sys_user users ON need.scheduling_user_id = users.id LEFT JOIN mes_building_bo_chu_job_directory jobDirectory ON need.nesting_job_id = jobDirectory.job_id LEFT JOIN plan_monomer monomer ON need.monomer_id = monomer.id AND monomer.bool_delete_enum = 0 LEFT JOIN sys_steel_classification steel ON part.steel_id = steel.id WHERE need.bool_delete_enum = 0
AND need.project_id IN
#{projectId}
AND need.task_order_id IN
#{taskOrderId}
AND part.steel_plate_type_enum in
#{item}
AND DATE_FORMAT( need.ask_complete_time, '%Y-%m' ) IN
#{yearMonth}
AND need.send_nesting_status = #{param.sendNestingStatus}
AND part.steel_id IN
#{taskType}
AND need.groups_id IN
#{groupId}
AND need.workshop_id IN
#{workshopId}
AND part.path = #{param.partSource}
AND part.specification like concat('%',#{param.specification},'%')
AND part.serial_number like concat('%',#{param.serialNumber},'%')
AND part.thick IN
#{thick}
AND part.width between #{param.minWidth} and #{param.maxWidth}
AND part.length between #{param.minLength} and #{param.maxLength}
AND part.bool_process = #{param.boolProcess}
AND need.issued_to_nesting_software_status = #{param.issuedToNestingSoftwareStatus}
AND part.material = #{param.material}
AND part.bool_send_directly = #{param.boolSendDirectly}
GROUP BY need.product_id,need.task_order_id, need.issued_to_nesting_software_status ORDER BY ask_complete_time,part.serial_number,part.specification DESC

    SELECT
      *
    FROM
      mes_building_bo_chu_job_directory
    WHERE
      bool_delete_enum = 0
      
        AND project_id = #{projectIdsStr}
      



      
        AND DATE_FORMAT( create_time, '%Y-%m-%d' ) >= #{startDate}
      
      
        AND DATE_FORMAT( create_time, '%Y-%m-%d' ) <= #{endDate}
      



      
          AND workshop_id IN
          
            #{wid}
          
      
      OR job_type = 0

SELECT mbbcjd.* FROM mes_building_bo_chu_job_directory mbbcjd WHERE mbbcjd.bool_delete_enum = 0
AND mbbcjd.job_name like CONCAT('%', #{name},'%')
AND DATE_FORMAT( mbbcjd.create_time, '%Y-%m-%d' ) >= #{startDate}
AND DATE_FORMAT( mbbcjd.create_time, '%Y-%m-%d' ) <= #{endDate}
AND mbbcjd.workshop_id IN
#{wid}
AND EXISTS(SELECT 1 FROM mes_building_bo_chu_nesting_result mbbcnr WHERE mbbcnr.bool_delete_enum = 0 AND mbbcnr.job_id = mbbcjd.job_id AND mbbcnr.cut_status = #{cutStatus})
OR (mbbcjd.job_type = 0 AND mbbcjd.bool_delete_enum = 0)
